using System;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class BibleVerseApp : MonoBehaviour
{
    [Serializable] public class Verse { public string reference; public string text; public string category; }
    static readonly Verse[] verses = {
        new Verse { reference="John 3:16", text="For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.", category="Faith" },
        new Verse { reference="Philippians 4:13", text="I can do all things through Christ which strengtheneth me.", category="Strength" },
        new Verse { reference="Psalm 23:1", text="The Lord is my shepherd; I shall not want.", category="Peace" },
        new Verse { reference="Proverbs 3:5", text="Trust in the Lord with all thine heart; and lean not unto thine own understanding.", category="Wisdom" }
    };
    readonly Color navy=new Color(.055f,.09f,.16f), gold=new Color(.93f,.70f,.28f), cream=new Color(.97f,.94f,.86f);
    Canvas canvas; Text body, status; int current; bool revealed;
    void Awake(){Application.targetFrameRate=60; BuildUI();}
    Text TextObject(string value,int size,Color color,Transform parent){var go=new GameObject("Text");go.transform.SetParent(parent,false);var t=go.AddComponent<Text>();t.text=value;t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=size;t.color=color;t.alignment=TextAnchor.MiddleCenter;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
    RectTransform Panel(string name,Transform parent,Color color,Vector2 size,Vector2 pos){var go=new GameObject(name);go.transform.SetParent(parent,false);var rt=go.AddComponent<RectTransform>();rt.sizeDelta=size;rt.anchoredPosition=pos;go.AddComponent<Image>().color=color;return rt;}
    Button ButtonObject(string label,Transform parent,Vector2 size,UnityEngine.Events.UnityAction action){var rt=Panel(label,parent,new Color(.13f,.20f,.30f),size,Vector2.zero);var b=rt.gameObject.AddComponent<Button>();b.onClick.AddListener(action);var t=TextObject(label,24,cream,rt);t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.sizeDelta=Vector2.zero;return b;}
    void BuildUI(){var eventSystem=new GameObject("EventSystem");eventSystem.AddComponent<UnityEngine.EventSystems.EventSystem>();eventSystem.AddComponent<UnityEngine.EventSystems.StandaloneInputModule>();var cgo=new GameObject("Canvas");canvas=cgo.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=cgo.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1080,1920);cgo.AddComponent<GraphicRaycaster>();var bg=Panel("Background",canvas.transform,navy,new Vector2(1080,1920),Vector2.zero);bg.anchorMin=Vector2.zero;bg.anchorMax=Vector2.one;bg.sizeDelta=Vector2.zero;var title=TextObject("Scripture\nMemory",64,gold,canvas.transform);title.rectTransform.anchoredPosition=new Vector2(0,720);title.rectTransform.sizeDelta=new Vector2(900,180);var sub=TextObject("Hide His word in your heart",26,cream,canvas.transform);sub.rectTransform.anchoredPosition=new Vector2(0,570);sub.rectTransform.sizeDelta=new Vector2(900,60);string scene=SceneManager.GetActiveScene().name;if(scene=="MaimMenu")Menu();else if(scene=="FlashCards")Flashcards();else if(scene=="FillInBlanks")FillBlanks();else if(scene=="MatchingCards")Matching();else Menu();}
    void Menu(){var y=260f;var a=ButtonObject("FLASHCARDS",canvas.transform,new Vector2(700,110),()=>SceneManager.LoadScene("FlashCards"));a.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,y);var b=ButtonObject("FILL IN THE BLANK",canvas.transform,new Vector2(700,110),()=>SceneManager.LoadScene("FillInBlanks"));b.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,y-160);var c=ButtonObject("MATCHING CARDS",canvas.transform,new Vector2(700,110),()=>SceneManager.LoadScene("MatchingCards"));c.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,y-320);}
    void CardLayout(){var card=Panel("VerseCard",canvas.transform,new Color(.96f,.91f,.78f),new Vector2(820,580),new Vector2(0,180));body=TextObject("",34,navy,card);body.rectTransform.sizeDelta=new Vector2(720,470);status=TextObject("",24,gold,canvas.transform);status.rectTransform.anchoredPosition=new Vector2(0,-220);status.rectTransform.sizeDelta=new Vector2(850,80);}
    void Flashcards(){CardLayout();ShowFlashcard();var a=ButtonObject("TAP CARD / REVEAL",canvas.transform,new Vector2(600,95),()=>{revealed=!revealed;ShowFlashcard();});a.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-350);var b=ButtonObject("NEXT VERSE",canvas.transform,new Vector2(600,95),()=>{current=(current+1)%verses.Length;revealed=false;ShowFlashcard();});b.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-480);BackButton();}
    void ShowFlashcard(){body.text=revealed?verses[current].text:verses[current].reference;status.text=revealed?"How well did you remember it?":"Think of the verse before revealing it";}
    void FillBlanks(){CardLayout();var v=verses[current];body.text=v.reference+"\n\n"+v.text.Replace("world","____");string[] opts={"world","night","mountain","water"};for(int i=0;i<4;i++){int index=i;var b=ButtonObject(opts[i],canvas.transform,new Vector2(360,85),()=>status.text=index==0?"Correct! Keep going.":"Try again.");b.GetComponent<RectTransform>().anchoredPosition=new Vector2(i%2==0?-210:210,i<2?-350:-460);}BackButton();}
    void Matching(){body=TextObject("Match the references with their verses",28,cream,canvas.transform);body.rectTransform.anchoredPosition=new Vector2(0,360);body.rectTransform.sizeDelta=new Vector2(900,80);for(int i=0;i<4;i++){var v=verses[i];var a=ButtonObject(v.reference,canvas.transform,new Vector2(390,120),()=>status.text="Card selected — find its matching verse");a.GetComponent<RectTransform>().anchoredPosition=new Vector2(-220,i<2?160:-20);var b=ButtonObject(v.text.Substring(0,Mathf.Min(42,v.text.Length))+"…",canvas.transform,new Vector2(390,120),()=>status.text="Keep matching cards!");b.GetComponent<RectTransform>().anchoredPosition=new Vector2(220,i<2?160:-20);}status=TextObject("",24,gold,canvas.transform);status.rectTransform.anchoredPosition=new Vector2(0,-430);status.rectTransform.sizeDelta=new Vector2(900,70);BackButton();}
    void BackButton(){var b=ButtonObject("BACK TO MENU",canvas.transform,new Vector2(420,75),()=>SceneManager.LoadScene("MaimMenu"));b.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,-620);}
}
